tool_args.command:
ssh bjb1-18228 'source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && echo "=== SmolVLA Spatial files ===" && ls -la /root/acr-vla-conformal-refinement/logs/eval_spatial*s42*.json /root/acr-vla-conformal-refinement/logs/eval_spatial*seed42*.json 2>/dev/null && echo "=== Extracting ===" && for f in $(ls /root/acr-vla-conformal-refinement/logs/eval_spatial*s42*.json /root/acr-vla-conformal-refinement/logs/eval_spatial*seed42*.json 2>/dev/null | sort -u); do echo "--- $(basename $f) ---"; python -c "
import json; d=json.load(open(\"$f\")); s=d.get(\"adaptive_stats\",{}); mode=d.get(\"mode\",\"?\")
print(f\"MODE={mode},SR={d[\"overall_success_rate\"]},TR={s.get(\"trigger_rate\",\"N/A\")},MCN={s.get(\"mean_correction_norm\",\"N/A\")},MU={s.get(\"mean_uncertainty\",\"N/A\")},TS={s.get(\"total_steps\",\"N/A\")},CAS={s.get(\"crm_applied_steps\",\"N/A\")}\")"; done'

